const input = $input.first().json;
let html = '';

if (typeof input === 'string') {
  html = input;
} else {
  const candidates = [input.body, input.data, input.response, input.html, ...Object.values(input)];
  html = candidates.find(v => typeof v === 'string' && v.includes('Volumen disponible')) || '';
}

if (!html || !html.includes('Volumen disponible')) {
  throw new Error('La respuesta de BioCloud no contiene "Volumen disponible". Se cancela para no publicar datos incorrectos.');
}

function decodeEntities(str) {
  const map = {
    '&nbsp;': ' ', '&amp;': '&', '&quot;': '"', '&#39;': "'",
    '&apos;': "'", '&lt;': '<', '&gt;': '>'
