const text = decodeEntities(
  html
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '\n')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '\n')
    .replace(/<!--[\s\S]*?-->/g, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(?:div|p|h[1-6]|li|section|article|tr|td)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
).replace(/\r/g, '\n');

const lines = text
  .split('\n')
  .map(s => s.replace(/\s+/g, ' ').trim())
  .filter(Boolean);

