function intFrom(line) {
  const m = String(line || '').match(/([\d.,]+)/);
  if (!m) return null;
  return Number(m[1].replace(/[.,]/g, ''));
}

function stationKey(name) {
  return name
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

const stations = [];

for (let i = 0; i < lines.length; i++) {
  if (!/^Volumen disponible$/i.test(lines[i])) continue;

  const name = lines[i - 1];
  const volume = intFrom(lines[i + 1]);
  if (!name || !Number.isFinite(volume)) continue;

  let vehicles = null;
  let queueMinutes = null;
  let address = null;

  for (let j = i + 2; j < Math.min(lines.length, i + 16); j++) {
    const line = lines[j];

    if (/^El volumen alcanza aprox\.? para$/i.test(line)) {
      vehicles = intFrom(lines[j + 1]);
      continue;
    }
    if (/^Un vehículo en cola avanza cada$/i.test(line)) {
      queueMinutes = intFrom(lines[j + 1]);
      continue;
    }
    if (/^UBICACION$/i.test(line) && j > 0) {
      address = lines[j - 1];
      break;
    }
    if (/^Volumen disponible$/i.test(line)) break;
  }

  stations.push({
    key: stationKey(name),
    name,
    address,
    liters: volume,
    vehiclesEstimated: vehicles,
    queueMinutes
  });
}

if (stations.length < 1) {
  throw new Error('No se extrajo ningún surtidor. Se cancela la publicación.');
}

return [{
  json: {
    sourceMeasuredAt,
    visibleStationCount: stations.length,
    stations
  }
}];

